import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Walk through Paintings: Egocentric World Models from Internet Priors","description":"","frontmatter":{"title":"Walk through Paintings: Egocentric World Models from Internet Priors","arxiv":"2601.15284","date":"2026-01-21","authors":"Anurag Bagchi, Zhipeng Bao, Homanga Bharadhwaj, Yu-Xiong Wang, Pavel Tokmakov, Martial Hebert","categories":"cs.CV","topics":"世界模型, 动作条件视频生成, 具身智能","outline":[2,2]},"headers":[],"relativePath":"papers/2601.15284.md","filePath":"papers/2601.15284.md","lastUpdated":null}'),l={name:"papers/2601.15284.md"};function e(m,s,i,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="walk-through-paintings-egocentric-world-models-from-internet-priors" tabindex="-1">Walk through Paintings: Egocentric World Models from Internet Priors <a class="header-anchor" href="#walk-through-paintings-egocentric-world-models-from-internet-priors" aria-label="Permalink to &quot;Walk through Paintings: Egocentric World Models from Internet Priors&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2601.15284" target="_blank" rel="noreferrer">2601.15284</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-01-21</td></tr><tr><td><strong>作者</strong></td><td>Anurag Bagchi, Zhipeng Bao, Homanga Bharadhwaj, Yu-Xiong Wang, Pavel Tokmakov, Martial Hebert</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把动作嵌入直接加到视频扩散模型已有的 denoising timestep 调制通路上，任何架构都能零改动变成动作条件世界模型，并用 SCS 指标把动作跟随度与视觉保真度分开度量。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>世界模型要回答的问题是：给定当前观测和一个动作，世界会变成什么样？注意这里的关键词不是&quot;一个合理的未来&quot;，而是&quot;<strong>正确的</strong>那个未来&quot;。视频生成模型早就能编出看起来合理的续帧，但那不等于它理解了每个动作的后果。</p><p>真正的瓶颈在数据。带动作标注的真实世界视频必须靠 agent 实际去交互才能采集，昂贵且稀缺。于是已有工作要么退到仿真器定义的窄数据集上训，要么为特定机器人、特定环境做定制设计，可扩展性都很差。Navigation World Models（NWM）在这条路上走得最远——它在多种机器人与人类的自我中心视频上训了一个 10 亿参数的扩散模型，实现了跨环境泛化。但即便如此，为每个新本体、每个新领域都收一遍大数据集仍然不现实。</p><p>论文提出的问题很直接：能不能复用在<strong>被动数据</strong>（互联网视频）上预训练好的现成视频模型，只用少量配对的动作–观测数据，把它转成世界模型？如果可以，世界模型的数据门槛就从&quot;为每个本体收集大规模交互数据&quot;降到&quot;少量微调数据 + 一个已有的视频 backbone&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>动作条件视频预测有很长的历史。Ha 与 Schmidhuber 的 World Models 用变分 RNN 模拟简单游戏；Visual Foresight 学会根据机器人动作预测未来帧并用 MPC 推物体；SV2P 引入随机隐变量建模多模态未来。这些工作证明了范式可行，但都局限在玩具仿真或单任务机器人配置里。</p><p>游戏领域出现了从像素与键盘输入端到端模拟整个游戏引擎的工作——GameGAN、DIAMOND（在 Atari 上用扩散世界模型保住视觉细节）、GameNGen（实时模拟完整 3D 游戏）。它们展示了扩散模型捕捉复杂动力学的潜力，但每一个都被限定在自己的领域内、从头用领域数据训练。</p><p>桌面操作方向（IRASim、Unified World Models、Ctrl-World）同样面临窄领域、静态相机、定制模型设计的限制。NWM 把范围拓宽到多种导航任务与本体，但论文精确指出其代价：它依赖昂贵的域内配对动作–观测数据，并且用了一个定制模型（CDiT），这两点共同限制了它的泛化上限。</p><p>两个并发工作构成最直接的对照。GrndCtrl 只是复用了 Cosmos 已有的动作条件实现；Ctrl-World 依赖定制的、模型特定的条件设计。作者的差异化很明确：<strong>框架与 backbone 架构无关，且支持更复杂的动作空间</strong>——从 3-DoF 移动机器人一直到 25-DoF 人形机器人的全身关节角。</p><p>评测侧也有缺口。视频生成沿用的 SSIM、PSNR、LPIPS 是逐帧感知指标，FVD 是分布级指标。世界模型工作直接借用它们评估预测未来，但高分往往不反映动作对齐——一个模型可以生成锐利真实、却在物理上执行了错误动作的帧。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>有几条已有线索在 2025 年已经很清楚。第一，扩散模型的预训练表示可以被&quot;重新用途化&quot;到完全不同的任务上：Zero-1-to-3 做新视角合成，Marigold 做单目深度，Pix2gestalt 做非模态分割，ReferEverything 做视频分割。这些工作的共同经验是——<strong>改动越小，预训练先验保留得越好，泛化越强</strong>。</p><p>第二，视频模型在被动互联网数据上学到的世界先验相当丰富，近期工作甚至称&quot;视频模型是 zero-shot learner 与 reasoner&quot;。既然如此，一个世界模型缺的不是对世界的理解，而是<strong>动作与视觉变化之间的绑定</strong>。</p><p>第三个是结构性观察，也是本文的技术支点：无论 U-Net 还是 DiT，无论 SVD 还是 Cosmos，所有现代视频扩散架构都有一条共同的通路——用 denoising timestep embedding <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 来调制网络激活（scale/shift/gate）。这是一条已经贯穿全网络、已经被训练好的、天然与&quot;时间步&quot;绑定的条件注入路径。</p><p>把三条线索接起来的推理就很自然了：如果我要注入一个&quot;每帧一个&quot;的条件（动作序列），而模型里已经有一条&quot;每步调制一次&quot;的通路，那么最不侵入的做法就是把动作嵌入<strong>加到</strong>这条通路上，而不是新建条件层。这样既不改架构，又能保证条件是帧特定的。这一步不需要新理论，它是在&quot;最大化复用预训练结构&quot;这一原则下的必然选择。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>预训练视频模型已经知道世界长什么样、怎么动，它只是不知道你的动作对应哪种变化。所以不需要教它世界，只需要教它这个映射。</p><p>而所有视频扩散架构，无论 U-Net 还是 DiT，都用 denoising timestep embedding 来调制每一层的激活。把动作嵌入直接加到这个 embedding 上，调制参数就变成了帧特定且动作对齐的，模型架构一行不用改，预训练表示一点不用破坏。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>设想一台 25-DoF 人形机器人站在实验室里，给它一段关节角序列：&quot;向前迈两步，然后右转&quot;。</p><p><strong>动作投影。</strong> 给定动作序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7252em;vertical-align:-0.0391em;"></span><span class="mord mathbf">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span></span></span></span>，用一串轻量 MLP 把每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span> 维动作向量映射到嵌入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3303em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathbf mtight">A</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span></span></span></span>。对有时间压缩的 backbone（VAE 时间下采样因子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，如 Cosmos），再用 1D 卷积把动作嵌入降采样到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，与 latent 帧率对齐。不同本体只换参数化：3-DoF 导航用标准的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">ϕ</span><span class="mclose">)</span></span></span></span>，25-DoF 人形用 1X 数据集的关节角表示，模块结构不变。SVD 变体用 sine–cosine 特征加小 MLP；Cosmos 变体因为时间压缩造成信息损失，改用表达力更强的 MLP。</p><p><strong>动作注入。</strong> 在模型施加 timestep 调制的每一处，把动作嵌入加进去：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1883em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">scale</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">shift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9115em;"><span style="top:-2.4231em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gate</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">.</span></span></span></span></span></p><p>人形机器人的情况多一项——很多身体部位不在相机视野内，所以额外把初始 agent 状态的嵌入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 也加进来。</p><p><strong>微调。</strong> 用 base 模型原本的预训练目标（denoising 或 flow matching），只是多了动作条件通路。动作投影模块的学习率设为 backbone 权重的 10 倍——SVD 变体是 1e-4 vs 1e-5，Cosmos 变体是 1e-5 vs 1e-6。全部实验只用 8 张 A100（NWM 用 64 张 H100）。最长的一次训练是 Cosmos-2B 在 1X 数据集上做 25-DoF 操作，8 天。</p><p><strong>推理。</strong> SVD 变体在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span> 下每次预测 8 帧、自回归两轮得 16 帧；Cosmos 变体在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">480</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">640</span></span></span></span> 下单次前向直接出 16 帧。因为是成块生成而非逐帧自回归，延迟远低于 NWM。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>方法本身的数学极简，核心就是 § 5 的那个加法式。真正需要展开的是评测指标 SCS，因为它承载了论文的第三项贡献。</p><p>动机是这样的：给定同一段初始观测和动作序列，两个模型的预测可能在 LPIPS、DreamSim 上得分接近，动作跟随行为却完全不同（论文图 3 展示了感知指标错误地偏向视觉更锐利但物理上不一致的样本）。此外，长时程导航里未来本身是多模态的——agent 走得越远，合理的未来越多，逐帧比对越没意义。</p><p>SCS 的构造分三步。第一步，裁掉那些只包含初始观测里未出现区域的帧，因为在那里&quot;结构对应&quot;根本没有定义；用 AllTracker 的稠密点跟踪自动检测&quot;首帧可见的点全部离开视野&quot;的时刻。第二步，人工标注关键场景结构——那些表观运动<strong>只</strong>来自 agent 自身运动的静态物体（建筑、树、家具）。限定在被动物体上减少了歧义，也让 SAM2 这类视频分割基础模型可以稳健地跟踪（论文验证了 SAM2 对生成视频的伪影具有鲁棒性）。第三步，在真值与预测序列上各跟踪一遍，按 mask IoU 平均：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">SCS</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.286em;vertical-align:-1.4138em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.4138em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8722em;"><span style="top:-2.11em;"><span class="pstrut" style="height:3.0448em;"></span><span class="mord"><span class="mord">∣</span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0448em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span><span style="top:-3.2198em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4374em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∪</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0448em;"><span style="top:-2.4542em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gt</span></span></span></span></span><span style="top:-3.2198em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3819em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span><span style="top:-3.2748em;"><span class="pstrut" style="height:3.0448em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.8722em;"><span class="pstrut" style="height:3.0448em;"></span><span class="mord"><span class="mord">∣</span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0448em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span><span style="top:-3.2198em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4374em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∩</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0448em;"><span style="top:-2.4542em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gt</span></span></span></span></span><span style="top:-3.2198em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3819em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3722em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">.</span></span></span></span></span></p><p>为什么这个式子能把动作跟随度与视觉保真度分开？因为 IoU 只看 mask 的空间位置与形状，完全不看纹理、颜色、清晰度。如果模型正确执行了&quot;右转 30 度&quot;，那么画面里的建筑就应当出现在特定位置，无论它渲染得糊不糊；反过来，一个渲染精美但转了 45 度的预测会被直接惩罚。论文附录展示了在高度扭曲的预测上 SAM2 仍能跟踪，因此 SCS 在生成保真度很差时依然可用——这正是&quot;解耦&quot;的操作性证据。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：复用预训练视频模型能否打过专门设计的世界模型？</strong> 在 RECON、SCAND、Tartan-Drive 三个导航数据集上微调，在 RECON 验证集上评测。两个变体在所有预测时程与所有指标上都超过 NWM，且<strong>时程越长优势越大</strong>：第 16 帧上 NWM 的 SCS 是 33.4，EgoWM(SVD) 是 55.2，EgoWM(Cosmos) 是 47.5。感知指标同样领先（Cosmos 的 LPIPS 0.33 vs NWM 0.45）。作者注意到 Cosmos 感知保真度更高（更强的预训练先验），SVD 结构一致性更稳（U-Net 无时间下采样）。</p><p><strong>问题二：预训练先验到底贡献了多少？</strong> 这是最干净的一项对照——在 1X 人形数据上训一个 <strong>SVD (scratch)</strong> 版本，架构完全相同只是不用预训练权重。第 16 帧上 SVD 预训练版 LPIPS 0.35 / SCS 34.4，scratch 版 LPIPS 0.47 / SCS 21.6。感知指标上的差距尤其大（DreamSim 0.18 vs 0.40），直接支持&quot;互联网规模被动预训练有价值&quot;这个核心 claim。</p><p><strong>问题三：这套设计能扩展到多复杂的动作空间？</strong> 从 3-DoF 移动机器人跳到 25-DoF 人形（全身主要关节 + 颈部 + 夹爪），架构零修改。人形导航的 SCS 在轨迹末端略低于 3-DoF 导航，作者归因于高维控制下需要对大量耦合关节与部分自我中心可见性做推理。操作任务上 SCS 反而更高（SVD 第 16 帧 76.6，Cosmos 67.7），因为操作时场景变化远小于导航——注意这也意味着操作任务上的 SCS 与导航任务上的不可直接横向比较。</p><p><strong>问题四：泛化的边界在哪？</strong> 用 3-DoF SVD 变体在<strong>画作</strong>里导航。模型在完全没有物理基础、不存在真实动力学的视觉域里依然正确执行运动指令（前进、转向、旋转），同时保持画作的笔触与美学特征。25-DoF 人形导航模型也能泛化到校园里全新的真实场景。这是全文最有说服力的定性证据——它说明动作条件是&quot;挂&quot;在预训练先验之上的一层薄映射，没有破坏 backbone 的开放世界能力。</p><p><strong>问题五：实用性如何？</strong> NWM 是逐帧自回归的，EgoWM 成块生成，延迟随帧数增加而拉开差距，最高 6 倍。同时 EgoWM 在更高分辨率下预测（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span> / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">480</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">640</span></span></span></span> vs NWM 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span>），为公平起见所有指标都降采样到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span> 计算。用 8 张 A100 对 64 张 H100，算力约少 8 倍。</p><p><strong>失败模式</strong>（作者主动披露）：操作中小物体的形状在遮挡后难以保持，物体恒常性仍是挑战（方块在操作中变形）；画作泛化上 Cosmos 变体更容易崩塌成真实世界场景，作者归因于 Cosmos 预训练数据更偏重真实物理数据；SVD 变体在需要快速想象大片新场景时会掉保真度，结构有时会消失、出现或变形。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> 所有视频扩散架构都靠 denoising timestep embedding 调制激活，把动作嵌入加到这条通路上就能零架构改动地把任意预训练视频模型转成动作条件世界模型。这一设计在 U-Net（SVD）与 DiT（Cosmos）上都成立，且动作空间从 3-DoF 移动机器人一路扩展到 25-DoF 人形全身关节角，覆盖导航与操作。在 RECON 上两个变体全面超过专门设计的 NWM，长时程优势尤为明显（第 16 帧 SCS 55.2 vs 33.4），同时延迟低至 1/6、分辨率高至 2 倍、算力少约 8 倍。一个从头训练的同架构对照组显著更差，直接证明互联网规模被动预训练是收益来源。作者还提出 SCS 指标——只用静态场景结构的 mask IoU 度量结构演化是否与动作一致，从而把动作跟随度从视觉保真度里剥离出来。</p><p><strong>3 句话版。</strong> 视频模型已经懂世界，缺的只是动作到视觉变化的绑定，而这个绑定可以挂在已有的 timestep 调制通路上。这样做保住了互联网先验，模型甚至能在画作里正确导航。SCS 指标则解决了&quot;感知指标会奖励好看但物理错误的预测&quot;这一评测缺口。</p><p><strong>1 句话版。</strong> 动作嵌入加进 timestep embedding，被动视频模型就变成了世界模型。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条：<strong>动作对视觉的影响可以被一个全局的、逐帧共享的调制信号充分表达</strong>。</p><p>timestep 调制的作用范围是整个网络的所有空间位置——它是一个全局的 scale/shift/gate。对于 3-DoF 导航，这个假设很合理：自车运动引起的是全画面的一致变换（视差、旋转），一个全局信号足以描述。但对于操作任务，动作的影响是<strong>高度局部的</strong>——夹爪捏住一个杯子时，只有杯子和手周围几十个像素应该变化，其余场景应当纹丝不动。用一个全局调制信号去表达局部因果，本质上是把空间定位的负担全部推给了 backbone 自己的注意力机制。</p><p>论文的证据恰好在这里露出裂缝。作者披露的第一个失败模式就是操作场景：小物体在被操作时形状扭曲，遮挡后无法保持物体恒常性（附录图 10 展示方块在操作中变形）。作者把原因归给&quot;底层视频生成 backbone 的局限&quot;，并期待未来更好的视频模型自然解决。这个归因是可能的，但存在一个同样合理的替代解释：<strong>全局调制在原理上就不适合表达局部接触动力学</strong>，换更强的 backbone 也不会消除这个结构性不匹配（这是笔者的推断，论文未做这一区分）。</p><p>区分这两种解释的实验并不难，但论文没有做：没有报告&quot;同一 backbone 下，全局 timestep 调制 vs 空间局部化的动作条件（如把动作嵌入与手部区域的空间位置绑定）&quot;的对比。缺少这个消融，&quot;架构无关的通用配方&quot;这一 claim 在操作类任务上的适用性就还是开放问题。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要 25-DoF 人形也不需要 8 天训练。一周内的最小验证聚焦最核心的 claim：<strong>timestep 调制通路足以承载动作条件</strong>。</p><p>数据：只用 RECON 的 3-DoF 导航子集（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">ϕ</span><span class="mclose">)</span></span></span></span>），抽 2000 条轨迹，每条取 16 帧。</p><p>实现：取一个小的开源 I2V 模型（SVD-XT 或 CogVideoX-2B）。训三个版本，算力预算相等：(a) 动作嵌入加到 timestep embedding（本文方案）；(b) 动作嵌入经 cross-attention 注入（常规做法）；(c) 动作序列拼接到输入 latent 通道。每版训 6 GPU-hours 级别。</p><p>测量：实现 SCS 需要人工标注静态结构，成本较高，可以简化——用 SAM2 在首帧自动分割出面积最大的 3 个静态区域（跳过人工挑选），在真值与预测视频上跟踪算 IoU，记作 SCS-auto。同时报告 LPIPS。</p><p>判定：若 (a) 的 SCS-auto 不低于 (b) 和 (c)，且 LPIPS 明显更好（说明预训练先验保留更完整），支持核心 claim。若 (b) 的 SCS 明显更高但 LPIPS 更差，说明这是一个&quot;控制精度 vs 先验保留&quot;的权衡而非纯粹的优势，论文的表述需要修正。</p><p>额外的廉价诊断：把训练好的 (a) 直接喂一张画作图片 + 前进指令，看是否复现&quot;走进画里&quot;的现象。这不需要任何指标，肉眼即可判断预训练先验是否被保住。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对 SCS 这个新指标本身——因为论文的核心量化结论（尤其是长时程上对 NWM 的巨大优势）几乎完全建立在它之上。</p><p>论证路线：SCS 只度量<strong>静态场景结构的 mask IoU</strong>。这意味着它对两类错误完全免疫。其一，动态元素的运动是否正确——路上的行人、开动的车、被操作物体的形变，全部不在被跟踪对象之列（作者明确说&quot;限定在被动物体上以减少歧义&quot;）。其二，新出现内容是否合理——转过拐角后新暴露的区域被裁掉不参与评分。换句话说，一个模型只要正确地把已知静态结构做刚性变换，SCS 就会很高，哪怕它把所有动态元素都冻住、把所有新区域都糊成一片。</p><p>这给出了对结果的替代解释：EgoWM 相对 NWM 的 SCS 优势，可能主要来自它更擅长做&quot;整体刚性视角变换&quot;（这正是大规模视频预训练最容易学到的能力），而非更好地理解动作后果。NWM 逐帧自回归、分辨率更低，在刚性变换的精度上天然吃亏。</p><p>具体反例实验：构造一个<strong>动态元素敏感测试集</strong>。从 SCAND（社会导航数据，含大量行人）里挑出行人显著运动的片段，定义 SCS-dynamic——跟踪行人 mask 而非静态结构，比较真值与预测的 IoU。如果 EgoWM 的 SCS-dynamic 相对 NWM 的优势远小于 SCS-static 的优势，甚至反转，就说明大部分增益来自刚性变换而非动力学理解。</p><p>第二个攻击点：SCS 依赖人工挑选跟踪对象。不同标注者会选到不同物体，而选择大的、近的、纹理丰富的物体会系统性抬高分数（SAM2 跟得准）。论文没有报告标注者间一致性，也没有报告&quot;随机选取跟踪对象&quot;下的方差。做一次标注消融——同一批视频用三组独立标注跑 SCS，看模型排序是否稳定。若排序会翻转，这个指标就还不够成熟到支撑跨论文比较。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：EgoWM 学的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">未来帧</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord cjk_fallback">观测</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">动作</span></span><span class="mclose">)</span></span></span></span>，也就是一个<strong>前向</strong>模型。它能告诉你&quot;执行这段动作会看到什么&quot;，但不能告诉你&quot;要看到那个画面该执行什么动作&quot;，也不能告诉你&quot;这段动作在物理上可行吗&quot;。所有关于动作可行性的知识都隐含在生成分布里，无法被查询。§ 9 指出的局部接触失败，某种程度上正是这个表述方式的后果——模型从未被要求解释&quot;为什么杯子会动&quot;。</p><p><strong>新 framing</strong>：不要只学前向动力学，而要学一个<strong>双向一致的动力学对</strong>——同一套参数同时支持前向预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与逆动力学 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，并用两者的循环一致性作为额外的自监督信号。这个转变的意义在于：逆动力学给了模型一个<strong>可以从无动作标注视频中学习的目标</strong>。互联网上有海量没有动作标签的自我中心视频，前向模型用不了它们（没有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>），但循环一致性可以——先用逆模型推一个伪动作，再用前向模型检验它是否重建出正确的下一帧。这把&quot;少量配对数据&quot;的约束进一步放松成&quot;少量配对数据 + 海量无标注视频&quot;。</p><p><strong>可借鉴的相邻领域工具</strong>：其一是无监督机器翻译里的 back-translation 与 dual learning，它们处理的正是&quot;两个方向各自缺监督、但闭环可以自监督&quot;的同构问题。其二是 latent action 学习（Genie、LAPO 系列），它们已经证明可以从纯视频中反解出一致的离散动作空间；把这类 latent action 与本文的真实关节角空间对齐，就得到了一个可以跨本体迁移的动作接口。</p><p><strong>第一个实验</strong>：在最小设置下验证&quot;循环一致性能否提供有用梯度&quot;。用 RECON 的 3-DoF 数据，在已训好的 EgoWM(SVD) 上额外接一个轻量逆动力学头（两帧 latent → 动作），先用配对数据把它训到收敛，测它在留出集上的动作重建误差作为基线。然后取一批 SCAND 中被刻意去掉动作标签的片段，用逆模型推伪动作，喂给冻结的前向模型重建下一帧，测重建误差与&quot;用真值动作重建&quot;的差距。如果伪动作的重建误差接近真值动作（比如相对差距 &lt; 20%），说明循环信号足够干净，可以用来做大规模无标注数据的联合训练；如果差距很大，说明逆问题在这个动作空间下欠定，需要先解决多解性再谈自监督。这个实验完全基于已有模型，一周内可完成。</p>',69)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
